#include "api/tiny_forward_persistent.h"
#include <cmath>
#include <iostream>
#include <vector>
int main(){using namespace vulkan_runtime::tiny;constexpr std::size_t w1=H*4*H,b1=4*H,w2=4*H*H,b2=H,group=w1+b1+w2+b2,total=3*group;std::vector<float>state(total);for(std::size_t i=0;i<total;++i)state[i]=float(i+1)*.001f;BaseCheckpoint c;c.version=4;c.group_mask=BaseCheckpointNormalization|BaseCheckpointFfn;c.gamma.assign(H,1.f);c.ffn_w1.assign(state.begin(),state.begin()+w1);c.ffn_b1.assign(state.begin()+w1,state.begin()+w1+b1);c.ffn_w2.assign(state.begin()+w1+b1,state.begin()+w1+b1+w2);c.ffn_b2.assign(state.begin()+w1+b1+w2,state.begin()+group);c.ffn_w1_m.assign(state.begin()+group,state.begin()+group+w1);c.ffn_b1_m.assign(state.begin()+group+w1,state.begin()+group+w1+b1);c.ffn_w2_m.assign(state.begin()+group+w1+b1,state.begin()+group+w1+b1+w2);c.ffn_b2_m.assign(state.begin()+group+w1+b1+w2,state.begin()+2*group);c.ffn_w1_v.assign(state.begin()+2*group,state.begin()+2*group+w1);c.ffn_b1_v.assign(state.begin()+2*group+w1,state.begin()+2*group+w1+b1);c.ffn_w2_v.assign(state.begin()+2*group+w1+b1,state.begin()+2*group+w1+b1+w2);c.ffn_b2_v.assign(state.begin()+2*group+w1+b1+w2,state.end());if(c.ffn_b2_v.size()!=b2||c.ffn_w1.front()!=state.front()||!std::isfinite(c.ffn_w2_v.back()))return 1;std::vector<float>roundtrip;roundtrip.insert(roundtrip.end(),c.ffn_w1.begin(),c.ffn_w1.end());roundtrip.insert(roundtrip.end(),c.ffn_b1.begin(),c.ffn_b1.end());roundtrip.insert(roundtrip.end(),c.ffn_w2.begin(),c.ffn_w2.end());roundtrip.insert(roundtrip.end(),c.ffn_b2.begin(),c.ffn_b2.end());roundtrip.insert(roundtrip.end(),c.ffn_w1_m.begin(),c.ffn_w1_m.end());roundtrip.insert(roundtrip.end(),c.ffn_b1_m.begin(),c.ffn_b1_m.end());roundtrip.insert(roundtrip.end(),c.ffn_w2_m.begin(),c.ffn_w2_m.end());roundtrip.insert(roundtrip.end(),c.ffn_b2_m.begin(),c.ffn_b2_m.end());roundtrip.insert(roundtrip.end(),c.ffn_w1_v.begin(),c.ffn_w1_v.end());roundtrip.insert(roundtrip.end(),c.ffn_b1_v.begin(),c.ffn_b1_v.end());roundtrip.insert(roundtrip.end(),c.ffn_w2_v.begin(),c.ffn_w2_v.end());roundtrip.insert(roundtrip.end(),c.ffn_b2_v.begin(),c.ffn_b2_v.end());if(roundtrip!=state)return 1;std::cout<<"FFN state pack: PASS\n";return 0;}
